#include "game/world_generation/terrain_mesh.cpp"
#include <cassert>
#include <future>
#include <iostream>
#include <set>
using namespace altaria;
using namespace altaria::caves;
using C=std::array<int,3>;
using P=std::array<float,3>;
static bool ellipsoid(const Chamber&room,int x,int y,int z){float d=0;int p[]={x,y,z};for(int a=0;a<3;a++){float q=(p[a]-room.center[a])/room.radius[a];d+=q*q;}return d<1;}
static void support_checks(){size_t cases=0,kept=0,removed=0,components=0;
for(int scenario=0;scenario<3;scenario++)for(int kind=0;kind<=int(FormationKind::ice_sheet);kind++)for(int id=1;id<=8;id++){
 Chamber room{uint64_t(id),{-50.125f,-80.37f,-19.23f},{20,18,23},2,false,"giant"};
 FormationRule rule;rule.id="judge:"+std::to_string(kind);rule.kind=FormationKind(kind);rule.radius={2.5f,7.5f};rule.height={8,18};if(rule.kind==FormationKind::ice_sheet)rule.water=FormationWater::wet;
 auto f=plan_formation(room,rule,0,8,9);assert(f.rock);
 auto world=[&](int x,int y,int z){FormationCell cell;float roof=scenario==1?-70.f+5*std::sin(x/5.f)*std::cos(z/7.f):-40.f;cell.rock=y<=roof&&y>-256;cell.carved=ellipsoid(room,x,y,z);cell.allowed=true;if(scenario==2){float dy=y-(room.center[1]+2),dz=z-(room.center[2]+2);cell.allowed=std::abs(x-room.center[0])>2.5f&&dy*dy+dz*dz>9;}
 cell.water=cell.rock&&cell.carved&&y<=int(room.center[1]-7);cell.liquid_top=int(room.center[1]-7);return cell;};
 auto mask=support_formation(f,world),again=support_formation(f,world);assert(mask.origin==again.origin&&mask.size==again.size&&mask.bits==again.bits);std::set<C> voxels;
 for(int z=mask.origin[2];z<mask.origin[2]+mask.size[2];z++)for(int y=mask.origin[1];y<mask.origin[1]+mask.size[1];y++)for(int x=mask.origin[0];x<mask.origin[0]+mask.size[0];x++)if(mask.contains({float(x),float(y),float(z)})){auto c=world(x,y,z);assert(c.rock&&c.carved&&c.allowed&&formation_voxel(f,{float(x),float(y),float(z)},c.water,c.lava,c.liquid_top));voxels.insert({x,y,z});}
 assert(voxels.size()==mask.kept);kept+=mask.kept;removed+=mask.removed;cases++;
 while(!voxels.empty()){std::vector<C> wave{*voxels.begin()};voxels.erase(wave[0]);bool anchored=false;for(size_t i=0;i<wave.size();i++)for(int axis=0;axis<3;axis++)for(int sign:{-1,1}){auto next=wave[i];next[axis]+=sign;auto host=world(next[0],next[1],next[2]);anchored|=(host.rock&&!host.carved)||(f.kind==FormationKind::ice_sheet&&axis==1&&sign==-1&&host.water);if(voxels.erase(next))wave.push_back(next);}assert(anchored);components++;}
}assert(cases==264&&kept>1000&&removed>0);std::cout<<"SUPPORT_JUDGE_PASS placements="<<cases<<" components="<<components<<" kept="<<kept<<" removed="<<removed<<" host/corridor/water_clipping deterministic\n";}
static void concurrent_support(){Config cfg;cfg.enabled=true;cfg.plan.floor=-256;cfg.plan.ceiling=256;cfg.plan.infernal_chance=0;cfg.plan.archetypes={default_archetypes().front()};cfg.plan.entrance_chance=0;cfg.plan.isolated_chance=0;Runtime runtime(cfg,1337,0,[](const std::vector<float>&x,const std::vector<float>&){std::vector<Column> c(x.size());for(auto&v:c)v.height=100;return c;},0,{},[](const Network&n){std::vector<Formation> result;if(n.region.x||n.region.z||n.chambers.empty())return result;FormationRule rule;rule.id="judge:concurrent";rule.kind=FormationKind::stalagmite;rule.radius={4,4};rule.height={10,10};result.push_back(plan_formation(n.chambers.front(),rule,0,8,9));return result;},[](const Column&c,int,int y,int){return y<=c.height;});auto owner=runtime.region({0,0});assert(owner&&!owner->formations.empty());auto f=owner->formations.front();Bounds box=f.box;for(int i=0;i<3;i++){box.lo[i]-=1;box.hi[i]+=1;}
 std::promise<void> go;auto start=go.get_future().share();auto run=[&]{start.wait();return runtime.query(box);};auto a=std::async(std::launch::async,run),b=std::async(std::launch::async,run);go.set_value();auto qa=a.get(),qb=b.get();assert(qa.support.count(f.id)&&qb.support.count(f.id));assert(qa.support.at(f.id).get()==qb.support.at(f.id).get());assert(qa.support.at(f.id)->kept>0);auto stats=runtime.stats();assert(stats.support_entries==1);std::cout<<"SUPPORT_CONCURRENCY_PASS shared_mask=true entries="<<stats.support_entries<<" kept="<<qa.support.at(f.id)->kept<<"\n";}
static P cross_test(P a,P b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
static P minus_test(P a,P b){for(int i=0;i<3;i++)a[i]-=b[i];return a;}
static void rectangle_checks(){size_t cases=0;for(int d=0;d<3;d++)for(bool positive:{false,true})for(int width:{1,3,32})for(int height:{1,7,768}){CollisionRect rect;rect.axis=d;rect.positive=positive;rect.corner={3,-448,11};rect.width=width;rect.height=height;std::array<P,4> points;points.fill({3,-448,11});int u=(d+1)%3,w=(d+2)%3;points[1][u]+=width;points[2][u]+=width;points[2][w]+=height;points[3][w]+=height;P normal{};normal[d]=positive?1.f:-1.f;Surface expected;quad(expected,points,{},normal);auto faces=rect.faces();float area=0;for(size_t i=0;i<6;i++){auto&v=expected.vertices[expected.indices[i]];assert((faces[i]==P{v.x,v.y,v.z}));}for(int t=0;t<2;t++){auto n=cross_test(minus_test(faces[t*3+1],faces[t*3]),minus_test(faces[t*3+2],faces[t*3]));assert(n[d]*normal[d]<0);area+=std::sqrt(n[0]*n[0]+n[1]*n[1]+n[2]*n[2])*.5f;}assert(area==float(width*height));cases++;}std::cout<<"COLLISION_RECT_JUDGE_PASS cases="<<cases<<" winding_matches_render=true area_exact=true\n";}
static void partial_checks(){Registry r;std::string error;BlockDef air;air.id=0;air.key="air";air.solid=false;assert(r.add(air,error));BlockDef stone;stone.id=1;stone.key="stone";assert(r.add(stone,error));size_t shapes=0,triangles=0,degenerate=0;std::vector<uint8_t> codes;for(int type=1;type<=7;type++)for(int turn=0;turn<4;turn++)codes.push_back(pack_shape(type,turn));for(int code=128;code<188;code++)codes.push_back(uint8_t(code));for(auto code:codes){Volume v;v.min_y=-192;v.height=4;v.columns.resize(34*34);v.data.resize(34*34*6);auto cell=voxel_index(v,8,1,8);v.data[cell]=1;v.shapes[cell]=code;MeshResult m;partial_blocks(m,v,r);assert(!m.solid.indices.empty());for(size_t i=0;i<m.solid.indices.size();i+=3){auto va=m.solid.vertices[m.solid.indices[i]],vb=m.solid.vertices[m.solid.indices[i+1]],vc=m.solid.vertices[m.solid.indices[i+2]];auto n=cross_test({vb.x-va.x,vb.y-va.y,vb.z-va.z},{vc.x-va.x,vc.y-va.y,vc.z-va.z});float area=n[0]*n[0]+n[1]*n[1]+n[2]*n[2];if(area<1e-10f){degenerate++;continue;}if(!(n[0]*va.nx+n[1]*va.ny+n[2]*va.nz<0)){std::cout<<"PARTIAL_WINDING_FAILURE code="<<int(code)<<" triangle="<<i/3<<" cross="<<n[0]<<","<<n[1]<<","<<n[2]<<" normal="<<va.nx<<","<<va.ny<<","<<va.nz<<" vertices="<<va.x<<","<<va.y<<","<<va.z<<" / "<<vb.x<<","<<vb.y<<","<<vb.z<<" / "<<vc.x<<","<<vc.y<<","<<vc.z<<std::endl;std::exit(1);}assert(va.x>=8&&va.x<=9&&va.y>=-191&&va.y<=-190&&va.z>=8&&va.z<=9);triangles++;}shapes++;}std::cout<<"PARTIAL_COLLIDER_JUDGE_PASS shapes="<<shapes<<" nondegenerate_triangles="<<triangles<<" degenerate_visual_triangles="<<degenerate<<" clockwise_and_bounds_match=true\n";}
int main(){std::cout<<std::unitbuf;support_checks();concurrent_support();rectangle_checks();partial_checks();}
